mapper.select:
SELECT a.id, a.project_id, a.project_name, a.competition_name, a.competition_level,
       a.award_level, a.award_certificate, a.status, a.reject_reason, a.create_time, a.update_time
FROM award a

    INNER JOIN project p ON a.project_id = p.id



        AND a.project_name LIKE CONCAT('%', #{projectName}, '%')


        AND a.competition_name LIKE CONCAT('%', #{competitionName}, '%')


        AND a.competition_level = #{competitionLevel}


        AND a.award_level = #{awardLevel}


        AND p.applicant_id = #{applicantId}


ORDER BY a.create_time DESC
